create function pg_temp.pause_queued_job()returns trigger language plpgsql as $$begin
 if new.created_by='e1000000-0000-4000-8000-000000000006'and new.kind='weekly'and new.patients=array['e2000000-0000-4000-8000-000000000001']::uuid[]then
  perform public.care_job_write('pause',jsonb_build_object('id',(select value#>>'{}'from inform_fixture where name='pause_second'),'version',1,'reason','Pausar tras seleccionar cola QA'));
 end if;return new;end$$;
create trigger care_job_pause_during_queue_qa after insert on private.care_informs for each row execute function pg_temp.pause_queued_job();
select pg_temp.care_assert(private.care_scheduler_tick()=1,'Pause after queue selection prevents a later attempt in the same tick');
select pg_temp.care_assert((select state='pending'and attempts=0 from private.care_job_runs where job_id=(select(value#>>'{}')::uuid from inform_fixture where name='pause_second')),'Paused selected run stays queued without consuming an attempt');
select pg_temp.care_assert(not exists(select 1 from private.care_job_attempts a join private.care_job_runs r on r.id=a.run_id where r.job_id=(select(value#>>'{}')::uuid from inform_fixture where name='pause_second')),'No attempt history invented for paused run');
drop trigger care_job_pause_during_queue_qa on private.care_informs;
set local role authenticated;
select public.care_job_write('resume',jsonb_build_object('id',(select value#>>'{}'from inform_fixture where name='pause_second'),'version',2,'reason','Reanudar cola existente QA'));
reset role;
select pg_temp.care_assert(private.care_scheduler_tick()=1,'Resumed queued run executes once without duplicating its period');
select pg_temp.care_assert((select state='succeeded'and attempts=1 from private.care_job_runs where job_id=(select(value#>>'{}')::uuid from inform_fixture where name='pause_second')),'Resume preserves authorization history and original pending run');
rollback;
